// Convert secondary keywords to array
function normalizeKeywords(value) {
  if (!value) {
    return [];
  }
  if (Array.isArray(value)) {
    return value.map(String).filter(Boolean);
  }
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) {
      return [];
    }
    try {
      const parsed = JSON.parse(trimmed);
      if (Array.isArray(parsed)) {
        return parsed.map(String).filter(Boolean);
      }
    } catch (error) {
      // ignore and fallback to split
    }
    return trimmed.split(',').map(segment => segment.trim()).filter(Boolean);
  }
  return [];
}

const idea = $json;
const keywords = normalizeKeywords(idea.keywords_secundarias);

const searchQueries = [
  idea.idea_title ? `${idea.idea_title} datos 2024` : null,
  idea.idea_title ? `${idea.idea_title} estadisticas clave` : null,
  idea.keyword_principal ? `${idea.keyword_principal} tendencias 2024` : null,
  idea.cluster_name ? `${idea.cluster_name} mercado actual` : null
].filter(Boolean).filter((value, index, self) => self.indexOf(value) === index);

const context = {
  idea_title: idea.idea_title,
  cluster_name: idea.cluster_name,
  keyword_principal: idea.keyword_principal,
  keywords_secundarias: keywords,
  project_name: idea.project_name,
  search_queries: searchQueries
};

const prompt = `Eres un analista senior de contenidos SEO con acceso a internet. Debes investigar la idea descrita a continuacion usando el modelo o4-mini-deep-research de OpenAI.

Objetivo:
1. Encontrar datos recientes (maximo 2021-2026 preferentemente) que respalden la idea.
2. Identificar estadisticas clave, tendencias y hallazgos relevantes.
3. Referenciar fuentes confiables (organismos, estudios, medios reconocidos).
4. Preparar un resumen ejecutivo y un outline de articulo basado en la evidencia.

Contexto de la idea (JSON):\n${JSON.stringify(context, null, 2)}

Instrucciones importantes:
- Usa las consultas sugeridas como punto de partida y agrega las que estimes necesarias.
- Verifica que los datos sean consistentes y cita siempre la fuente con formato ORGANIZACION, AÑO.
- Responde EXCLUSIVAMENTE con JSON valido (sin markdown, sin comentarios).
- Usa exactamente la siguiente estructura con claves en mayuscula/minuscula segun se muestra:
{
  "Idea": "Resumen de la idea investigada",
  "Resumen": "Parrafo sintetico de maximo 4 oraciones",
  "DatosClave": [
    "Dato concreto con cifra o hallazgo (Fuente, Año)",
    "Otro dato relevante (Fuente, Año)"
  ],
  "Tendencias": [
    "Tendencia explicada brevemente (Fuente, Año)",
    "Otra tendencia"
  ],
  "Insights": [
    "Insight accionable derivado de la investigacion"
  ],
  "Fuentes": [
    {
      "Nombre": "Organizacion o medio",
      "Cita": "Nombre corto, Año",
      "URL": "https://...",
      "Tipo": "Reporte | Estudio | Articulo",
      "Notas": "Una frase con lo mas relevante"
    }
  ],
  "ConsultasSugeridas": [
    "Consulta recomendada para profundizar",
    "Otra consulta"
  ],
  "Outline": [
    {
      "Seccion": "Titulo de la seccion",
      "Enfoque": "Que cubrir",
      "Preguntas": ["Pregunta opcional"]
    }
  ]
}

Si no encuentras suficientes datos fiables, indica "Resumen" vacio y deja comentarios en "Insights" explicando la limitacion.`;

return [{
  json: {
    idea_id: idea.id,
    idea_title: idea.idea_title,
    idea_category: idea.categoria,
    idea_status: idea.status,
    keyword_cluster_id: idea.keyword_cluster_id,
    cluster_name: idea.cluster_name,
    project_name: idea.project_name,
    keyword_principal: idea.keyword_principal,
    keywords_secundarias: keywords,
    base_search_queries: searchQueries,
    prompt: prompt
  }
}];

// Helper functions
function normalizeStringArray(value) {
  if (!value) {
    return [];
  }
  if (Array.isArray(value)) {
    return value
      .map(entry => (typeof entry === 'string' ? entry.trim() : entry && typeof entry === 'object' && entry.text ? String(entry.text) : ''))
      .map(entry => entry.replace(/\s+/g, ' ').trim())
      .filter(Boolean);
  }
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) {
      return [];
    }
    if (trimmed.startsWith('[')) {
      try {
        const parsed = JSON.parse(trimmed);
        return normalizeStringArray(parsed);
      } catch (error) {
        // ignore
      }
    }
    return trimmed.split(/\n|\r|,/).map(part => part.replace(/\s+/g, ' ').trim()).filter(Boolean);
  }
  return [];
}

function normalizeSources(value) {
  if (!value) {
    return [];
  }
  if (!Array.isArray(value)) {
    if (typeof value === 'string') {
      const trimmed = value.trim();
      if (!trimmed) {
        return [];
      }
      try {
        const parsed = JSON.parse(trimmed);
        if (Array.isArray(parsed)) {
          return normalizeSources(parsed);
        }
      } catch (error) {
        // ignore
      }
      return [{
        Nombre: trimmed,
        Cita: trimmed,
        URL: null,
        Tipo: null,
        Notas: null
      }];
    }
    return [];
  }
  return value.map(entry => {
    if (typeof entry === 'string') {
      return {
        Nombre: entry,
        Cita: entry,
        URL: null,
        Tipo: null,
        Notas: null
      };
    }
    if (entry && typeof entry === 'object') {
      return {
        Nombre: entry.Nombre || entry.nombre || entry.Titulo || entry.titulo || '',
        Cita: entry.Cita || entry.cita || entry.Referencia || entry.referencia || '',
        URL: entry.URL || entry.url || null,
        Tipo: entry.Tipo || entry.tipo || entry.Formato || entry.formato || null,
        Notas: entry.Notas || entry.notas || entry.Resumen || entry.resumen || ''
      };
    }
    return {
      Nombre: '',
      Cita: '',
      URL: null,
      Tipo: null,
      Notas: ''
    };
  });
}

function sanitizeForSql(value) {
  if (value === null || value === undefined) {
    return null;
  }
  return String(value).replace(/\u0000/g, '').replace(/'/g, "''");
}

function sanitizeJsonForSql(value) {
  return JSON.stringify(value ?? null).replace(/\u0000/g, '').replace(/'/g, "''");
}

// --- utilería para respuestas incompletas ---
function buildIncompleteResult(statusLabel, promptData, httpResponse, message) {
  const usage = httpResponse.usage || {};
  const tokensUsed = usage.total_tokens ?? usage.output_tokens ?? usage.completion_tokens ?? null;
  const costEstimate = usage.total_cost ?? usage.total_cost_usd ?? usage.cost ?? null;

  return [{
    json: {
      idea_id: promptData.idea_id,
      keyword_cluster_id: promptData.keyword_cluster_id,
      cluster_name: promptData.cluster_name,
      idea_title: promptData.idea_title,
      idea_category: promptData.idea_category,
      model_used: httpResponse.model || 'o4-mini-deep-research',
      status: statusLabel,
      error_message: message || httpResponse.error || null,
      incomplete_details: httpResponse.incomplete_details || {},
      tokens_used: tokensUsed,
      cost_estimate: costEstimate,
      search_queries_sql: '[]',
      research_json_sql: '{}',
      summary_sql: null,
      key_insights_sql: '[]',
      datos_clave_sql: '[]',
      tendencias_sql: '[]',
      fuentes_sql: '[]',
      raw_response_sql: sanitizeJsonForSql(httpResponse)
    }
  }];
}

// --- Extraer texto desde la respuesta del endpoint /v1/responses ---
const httpResponse = $json.body ?? $json ?? {};
const promptData = $items('Preparar Prompt Investigacion')[$itemIndex].json;
const status = httpResponse.status || 'unknown';

if (status !== 'completed') {
  return buildIncompleteResult(status, promptData, httpResponse, httpResponse.error || null);
}

let responseText = '';
const outputs = Array.isArray(httpResponse.output)
  ? httpResponse.output
  : Array.isArray(httpResponse.outputs)
    ? httpResponse.outputs
    : [];

if (outputs.length) {
  const firstOutput = outputs[0] ?? {};
  if (Array.isArray(firstOutput.content) && firstOutput.content.length) {
    const textPart =
      firstOutput.content.find(part => typeof part.text === 'string' && part.text.trim()) ||
      firstOutput.content.find(part => typeof part === 'string') ||
      firstOutput.content[0];
    if (typeof textPart === 'string') {
      responseText = textPart;
    } else if (textPart && typeof textPart === 'object') {
      responseText = textPart.text || textPart.value || '';
    }
  } else if (typeof firstOutput === 'string') {
    responseText = firstOutput;
  } else if (firstOutput && typeof firstOutput === 'object' && typeof firstOutput.text === 'string') {
    responseText = firstOutput.text;
  }
}

if (!responseText && typeof httpResponse.output_text === 'string' && httpResponse.output_text.trim()) {
  responseText = httpResponse.output_text;
} else if (!responseText && Array.isArray(httpResponse.output_text)) {
  responseText = httpResponse.output_text.join('\n');
}

if (!responseText) {
  return buildIncompleteResult('no_text_found', promptData, httpResponse, 'No se encontró texto en la respuesta del modelo.');
}

// --- Limpiar y parsear ---
let cleaned = String(responseText).trim();
if (cleaned.startsWith('```json')) {
  cleaned = cleaned.replace(/^```json\s*/i, '').replace(/```$/i, '');
} else if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```\s*/i, '').replace(/```$/i, '');
}

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (error) {
  return buildIncompleteResult('json_parse_error', promptData, httpResponse, 'Respuesta no es JSON válido: ' + error.message);
}

// --- Normalización y armado de respuesta ---
const datosClave = normalizeStringArray(parsed.DatosClave || parsed.datos_clave);
const tendencias = normalizeStringArray(parsed.Tendencias || parsed.tendencias);
const insights = normalizeStringArray(parsed.Insights || parsed.insights);
const outline = Array.isArray(parsed.Outline || parsed.outline) ? parsed.Outline || parsed.outline : [];
const consultas = normalizeStringArray(parsed.ConsultasSugeridas || parsed.consultas || parsed.search_queries);
const fuentes = normalizeSources(parsed.Fuentes || parsed.fuentes);

const researchJson = {
  Idea: parsed.Idea || parsed.idea || promptData.idea_title,
  Resumen: parsed.Resumen || parsed.resumen || '',
  DatosClave: datosClave,
  Tendencias: tendencias,
  Insights: insights,
  Fuentes: fuentes,
  ConsultasSugeridas: consultas,
  Outline: outline
};

const combinedQueries = Array.from(new Set([...(promptData.base_search_queries || []), ...consultas]));
const usage = httpResponse.usage || {};
const tokensUsed = usage.total_tokens ?? usage.output_tokens ?? usage.completion_tokens ?? null;
const costEstimate = usage.total_cost ?? usage.total_cost_usd ?? usage.cost ?? null;

return [{
  json: {
    idea_id: promptData.idea_id,
    keyword_cluster_id: promptData.keyword_cluster_id,
    cluster_name: promptData.cluster_name,
    idea_title: promptData.idea_title,
    idea_category: promptData.idea_category,
    model_used: httpResponse.model || 'o4-mini-deep-research',
    status: 'completed',
    summary: researchJson.Resumen,
    summary_sql: researchJson.Resumen ? sanitizeForSql(researchJson.Resumen) : null,
    datos_clave: datosClave,
    tendencias: tendencias,
    insights: insights,
    fuentes: fuentes,
    outline: outline,
    search_queries: combinedQueries,
    tokens_used: tokensUsed,
    cost_estimate: costEstimate,
    research_json: researchJson,
    research_json_sql: sanitizeJsonForSql(researchJson),
    datos_clave_sql: sanitizeJsonForSql(datosClave),
    tendencias_sql: sanitizeJsonForSql(tendencias),
    key_insights_sql: sanitizeJsonForSql(insights),
    fuentes_sql: sanitizeJsonForSql(fuentes),
    search_queries_sql: sanitizeJsonForSql(combinedQueries),
    raw_response_sql: sanitizeJsonForSql(httpResponse)
  }
}];

const researchData = $items('Parse Research JSON')[$itemIndex]?.json || {};
const reportRow = $items('Guardar Research Report')[$itemIndex]?.json || {};
const ideaRow = $json || {};

return [{
  json: {
    idea_id: researchData.idea_id || ideaRow.idea_id || null,
    idea_title: researchData.idea_title || ideaRow.idea_title || null,
    cluster_name: researchData.cluster_name || ideaRow.cluster_name || null,
    status: researchData.status || ideaRow.status || 'unknown',
    research_report_id: reportRow.id ?? null,
    research_summary: researchData.summary ?? null,
    datos_clave: researchData.datos_clave ?? [],
    tendencias: researchData.tendencias ?? [],
    insights: researchData.insights ?? [],
    fuentes: researchData.fuentes ?? [],
    outline: researchData.outline ?? [],
    search_queries: researchData.search_queries ?? [],
    tokens_used: researchData.tokens_used ?? null,
    cost_estimate: researchData.cost_estimate ?? null,
    error_message: researchData.error_message ?? null,
    incomplete_details: researchData.incomplete_details ?? {},
    updated_at: reportRow.updated_at ?? null
  }
}];

const results = $json.research_results || [];

const totalCompleted = results.filter(item => item.status === 'completed').length;

return [{
  json: {
    status: totalCompleted === results.length && results.length ? 'success' : (results.length ? 'partial' : 'info'),
    total_ideas_processed: results.length,
    total_reports_created: totalCompleted,
    total_failed: results.length - totalCompleted,
    reports_details: results.map(item => ({
      idea_id: item.idea_id,
      idea_title: item.idea_title,
      cluster_name: item.cluster_name,
      research_report_id: item.research_report_id,
      status: item.status,
      resumen: item.research_summary,
      datos_clave: item.datos_clave,
      tendencias: item.tendencias,
      fuentes: item.fuentes,
      outline: item.outline,
      search_queries: item.search_queries,
      tokens_used: item.tokens_used ?? null,
      cost_estimate: item.cost_estimate ?? null,
      error_message: item.error_message ?? null,
      updated_at: item.updated_at
    })),
    processing_time: new Date().toISOString()
  }
}];

return [{
  json: {
    status: 'info',
    message: 'No hay ideas pendientes con categoria Requiere investigación sin research report generado',
    total_ideas_processed: 0,
    total_reports_created: 0,
    reports_details: []
  }
}];
